#include <bits/stdc++.h>

int ri() {
	int n;
	scanf("%d", &n);
	return n;
}

bool is_prefix(const std::string &s, const std::string &t) {
	if (s.size() > t.size()) return false;
	return s == t.substr(0, s.size());
}

int main() {
	int q = ri();

	std::multiset<std::string> x;
	std::multiset<std::string> y;

	for (int i = 0; i < q; i++) {
		int t = ri();
		std::string s;
		std::cin >> s;
		if (t == 1) {
			auto itr = x.upper_bound(s);
			if (itr != x.begin() && is_prefix(*std::prev(itr), s)) {}
			else {
				while (itr != x.end() && is_prefix(s, *itr)) itr = x.erase(itr);
				itr = y.lower_bound(s);
				while (itr != y.end() && is_prefix(s, *itr)) itr = y.erase(itr);
				x.insert(s);
			}
		} else {
			auto itr = x.upper_bound(s);
			if (itr != x.begin() && is_prefix(*std::prev(itr), s)) {}
			else {
				y.insert(s);
			}
		}
		printf("%d\n", (int) y.size());
	}

	return 0;
}

use std::collections::BTreeSet;

use ac_library::FenwickTree;
use itertools::Itertools;

fn main() {
    proconio::input! {
        q: usize,
        queries: [(u8, String); q],
    }
    let mut strs = queries.iter().map(|x| &x.1).collect_vec();
    strs.sort();

    let mut set = BTreeSet::new();
    let mut removed = FenwickTree::new(q, 0i32);
    for (i, (t, s)) in queries.iter().enumerate() {
        let pos = strs.binary_search(&s).unwrap();
        if *t == 1 {
            let x = strs.partition_point(|&st| st < s);
            let y = x + strs[x..].partition_point(|&st| st.starts_with(s));
            let poss = set.range((x, 0)..(y, 0)).copied().collect_vec();
            for pos in poss {
                set.remove(&pos);
            }
            removed.add(x, 1);
            removed.add(y, -1);
        } else {
            if removed.sum(..=pos) == 0 {
                set.insert((pos, i));
            }
        }
        println!("{}", set.len());
    }
}

use proconio::input;

fn main() {
    input! {
        q: usize,
        mut queries: [(u8, String); q],
    }
    queries.push((u8::MAX, String::new()));
    let mut sorted = (0..q).collect::<Vec<_>>();
    sort_queries(0, &queries, &mut sorted);
    let mut pref_stack = vec![q];
    let mut decr_stack = vec![usize::MAX];
    let mut ans = vec![0; q + 1];
    for &q_id in &sorted {
        while !queries[q_id]
            .1
            .starts_with(&queries[*pref_stack.last().unwrap()].1)
        {
            if *decr_stack.last().unwrap() == pref_stack.pop().unwrap() {
                decr_stack.pop().unwrap();
            }
        }
        pref_stack.push(q_id);
        if queries[q_id].0 == 1 {
            if *decr_stack.last().unwrap() > q_id {
                decr_stack.push(q_id);
            }
        } else {
            ans[q_id] += 1;
            ans[(*decr_stack.last().unwrap()).clamp(q_id, q)] -= 1;
        }
    }
    for i in 1..=q {
        ans[i] += ans[i - 1];
    }
    for &ans in &ans[..q] {
        println!("{ans}");
    }
}

fn sort_queries(depth: usize, queries: &[(u8, String)], sorted: &mut [usize]) {
    let mut buckets = std::array::from_fn::<_, 28, _>(|_| Vec::new());
    for &i in &*sorted {
        if queries[i].1.len() == depth {
            buckets[usize::from(queries[i].0 - 1)].push(i);
        } else {
            let c = queries[i].1.as_bytes()[depth] - b'a';
            buckets[c as usize + 2].push(i);
        }
    }
    let mut start = 0;
    for i in 0..28 {
        let end = start + buckets[i].len();
        sorted[start..end].copy_from_slice(&buckets[i]);
        if 2 <= i && start + 1 < end {
            sort_queries(depth + 1, queries, &mut sorted[start..end]);
        }
        start = end;
    }
}
